inline eventio::Json merge_joint_dense_packet_patch_v1(eventio::Json j,eventio::Json patch){
if(j.at("schema")!="rinkfit.joint_packet.v1"||patch.at("schema")!="rinkfit.joint_packet.v1")throw std::runtime_error("dense parent packet schema");if(j.contains("native_material_identity_revision")&&!j.contains("resolved_native_identity_revision_chain"))j["resolved_native_identity_revision_chain"]=eventio::Json::array({j.at("native_material_identity_revision")});if(j.contains("native_print_identity_rebind")&&!j.contains("resolved_native_print_identity_revision_chain"))j["resolved_native_print_identity_revision_chain"]=eventio::Json::array({j.at("native_print_identity_rebind")});if(j.contains("native_source_measurement_revision")&&!j.contains("resolved_native_source_measurement_revision_chain"))j["resolved_native_source_measurement_revision_chain"]=eventio::Json::array({j.at("native_source_measurement_revision")});const std::set<std::string>appendable={"groups","queries","source_manifests","recapture_rows","engineering_pixel_dependency_groups.groups"};auto app=patch.contains("dense_parent_append")?std::move(patch["dense_parent_append"]):eventio::Json::object();for(auto&v:app.items()){if(!appendable.count(v.key())||!v.value().is_array())throw std::runtime_error("unsupported dense append path");if(v.key()=="engineering_pixel_dependency_groups.groups"){if(patch.contains("engineering_pixel_dependency_groups"))throw std::runtime_error("dense dependency append/override conflict");auto&dst=j["engineering_pixel_dependency_groups"]["groups"];if(!dst.is_array())throw std::runtime_error("parent dependency group schema");for(auto&x:v.value())dst.push_back(std::move(x));}else{if(patch.contains(v.key()))throw std::runtime_error("dense append/override conflict");if(!j.contains(v.key()))j[v.key()]=eventio::Json::array();if(!j.at(v.key()).is_array())throw std::runtime_error("parent append field is not array");for(auto&x:v.value())j[v.key()].push_back(std::move(x));}}for(auto&v:patch.items()){if(v.key()=="dense_parent_append")continue;if(v.key()=="source_row_ids"||v.key()=="source_dataset_ids"||v.key()=="source_family_ids")throw std::runtime_error("dense prefix ID registry may not be overridden");j[v.key()]=std::move(v.value());}if(j.contains("native_material_identity_revision")){auto& chain=j["resolved_native_identity_revision_chain"];if(chain.is_null())chain=eventio::Json::array();const auto& latest=j.at("native_material_identity_revision");if(chain.empty()||chain.back()!=latest)chain.push_back(latest);}if(j.contains("native_print_identity_rebind")){auto& chain=j["resolved_native_print_identity_revision_chain"];if(chain.is_null())chain=eventio::Json::array();const auto& latest=j.at("native_print_identity_rebind");if(chain.empty()||chain.back()!=latest)chain.push_back(latest);}if(j.contains("native_source_measurement_revision")){auto& chain=j["resolved_native_source_measurement_revision_chain"];if(chain.is_null())chain=eventio::Json::array();const auto& latest=j.at("native_source_measurement_revision");if(chain.empty()||chain.back()!=latest)chain.push_back(latest);}
 return j;
}
// Read only authenticated descendants of a previously consumed original source
// document. This reuses parsed definitions, never a mathematical pass result.
template<class Authorize,class Read>
eventio::Json extend_joint_dense_packet_document_v1(const std::filesystem::path&target,const std::filesystem::path&parent,const std::string&parent_sha,const eventio::Json&verified_parent,Authorize authorize,Read read,eventio::Json*consumed=nullptr){
 using J=eventio::Json;auto normalize=[](const auto&p){return std::filesystem::absolute(p).lexically_normal();};const auto base=normalize(parent);authorize(base);eventio::verify(base,parent_sha);
 std::vector<std::pair<std::filesystem::path,J>> patches;std::set<std::string>seen;auto path=normalize(target);
 while(path!=base){if(!seen.insert(path.u8string()).second)throw std::runtime_error("cyclic dense extension");authorize(path);auto patch=read(path);
  if(patch.contains("resolved_native_identity_revision_chain")||patch.contains("resolved_native_print_identity_revision_chain")||patch.contains("resolved_native_source_measurement_revision_chain"))throw std::runtime_error("resolved review chain cannot be supplied by packet input");
  if(!patch.contains("dense_parent_packet"))throw std::runtime_error("incremental dense target is not descendant of verified original parent");const auto ref=patch.at("dense_parent_packet");auto next=std::filesystem::u8path(ref.at("file").template get<std::string>());if(next.is_relative())next=path.parent_path()/next;next=normalize(next);eventio::verify(next,ref.at("sha256"));if(next==base&&ref.at("sha256")!=parent_sha)throw std::runtime_error("incremental dense parent SHA differs from consumed original");
  patches.push_back({path,std::move(patch)});path=next;
 }
 auto j=verified_parent;j.erase("runtime_reviewed_statistical_marginals");j.erase("runtime_effective_input_v1");
 for(auto it=patches.rbegin();it!=patches.rend();++it){if(consumed)consumed->push_back({{"file",it->first.u8string()},{"sha256",eventio::file_sha256(it->first)}});j=merge_joint_dense_packet_patch_v1(std::move(j),std::move(it->second));}
 return j;
}
